def framePiLpEquivFin (p : ℝ≥0∞) [Fact (1 ≤ p)] (n : ℕ) :
    PiLp p (fun _ : FrameIndex n => ℝ) ≃ₗᵢ[ℝ] PiLp p (fun _ : Fin (4 ^ n) => ℝ) :=
  LinearIsometryEquiv.piLpCongrLeft p ℝ ℝ (frameIndexEquivFin n)

